var e={id:`k1-60-preimplantasyon-genetik-tani-pgt`,sira:60,kurul:1,ders:`Tıbbi Genetik`,konu:`Preimplantasyon Genetik Tanı (PGT)`,ogretim_uyesi:`Dr. Öğr. Üyesi Serap Arslan`,tarih:`2026-10-14`,soru_sayisi:65,kazanimlar:[{no:1,metin:`Preimplantasyon genetik tanı (PGD) ve preimplantasyon genetik taramanın (PGS) tanımını ve birbirinden farkını açıklamak`,sorular:[{id:`k1-60-q01`,kazanim:1,zorluk:`kolay`,soru:`Preimplantasyon genetik tanının (PGD) en önemli yararı hangisidir?`,secenekler:{A:`Gebelik sırasında amniyosentezi zorunlu kılması`,B:`Hastayı olası gebelik terminasyonundan (medikal abortus) koruması`,C:`Yalnızca doğum sonrası tanı sağlaması`,D:`IVF gereksinimini ortadan kaldırması`,E:`Tüm embriyoların transfer edilmesini sağlaması`},dogru:`B`,aciklama:`PGD'de embriyolar transfer öncesi test edilir; sağlıklı embriyo transfer edildiğinden gebelik terminasyonu ihtiyacı ortadan kalkar.`,sik_aciklamalari:{A:`PGD sonrası doğrulama önerilebilir, ancak temel yarar terminasyondan korunmadır.`,B:`Doğru: PGD'nin en önemli yararıdır.`,C:`PGD implantasyon öncesi yapılır.`,D:`PGD yardımlı üreme tekniği gerektirir.`,E:`Yalnızca sağlıklı embriyolar transfer edilir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-60-q02`,kazanim:1,zorluk:`orta`,soru:`PGS (preimplantasyon genetik tarama) ile ilgili hangisi doğrudur?`,secenekler:{A:`Gebelikte fetal kandan yapılan testtir`,B:`Bilinen bir tek gen mutasyonunun embriyoda aranmasıdır`,C:`Aday embriyolarda anöploidi taraması yapılarak öploid embriyonun transfer edilmesidir`,D:`Yalnızca HLA uyumu için yapılır`,E:`Yalnızca erkek infertilitesinde uygulanır`},dogru:`C`,aciklama:`PGS tüp bebek başarısını artırmaya yönelik anöploidi taramasıdır; özellikle ileri anne yaşında kullanılır.`,sik_aciklamalari:{A:`Fetal kan örneklemesi kordosentezdir.`,B:`Bilinen mutasyonun aranması PGD (PGT-M) kapsamındadır.`,C:`Doğru: PGS'nin tanımıdır.`,D:`HLA tiplemesi PGD'nin özel bir uygulamasıdır.`,E:`PGS'nin ana kullanım alanı ileri anne yaşıdır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-60-q03`,kazanim:1,zorluk:`zor`,soru:`PGD ve PGS karşılaştırıldığında aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`PGD gebelik sırasında amniyon sıvısından yapılır`,B:`PGS yalnızca tek gen hastalıklarında uygulanır`,C:`PGD ve PGS'nin amacı aynıdır`,D:`PGD bilinen genetik riski olan ailede spesifik hastalığın tanısına, PGS ise genel anöploidi taramasıyla gebelik başarısını artırmaya yöneliktir`,E:`PGS ileri anne yaşında kullanılmaz`},dogru:`D`,aciklama:`PGD bilinen riskli ailelerde hastalıklı embriyoyu ayırmaya, PGS ise öploid embriyo seçerek IVF başarısını artırmaya yöneliktir.`,sik_aciklamalari:{A:`PGD implantasyon öncesi embriyoda yapılır.`,B:`PGS anöploidi taramasıdır.`,C:`Amaçları farklıdır: PGD ve PGS'nin amacı aynıdır.`,D:`Doğru: iki yaklaşımın farkıdır.`,E:`PGS ileri anne yaşında yaygın kullanılır.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k01-q04`,kazanim:1,zorluk:`orta`,soru:`Talasemili çocuk öykülü çift ile 40 yaşındaki IVF çifti danışmanlıkta karşılaştırılıyor. İlkinde mutasyon analizi, ikincisinde anöploidi taraması planlanıyor. Hangi açıklama doğrudur?`,secenekler:{A:`PGD ve PGS aynı işlemdir`,B:`PGS tek gen hastalıklarını tanımlar`,C:`Beta talasemili çocuk öykülü çiftte embriyoların test edilip sağlıklısının transferi PGD'dir ve terminasyondan korur; ileri anne yaşındaki çiftte anöploidi taramasıyla öploid transferi PGS'dir`,D:`PGD'nin terminasyondan koruma yararı yoktur`,E:`PGS Mendeliyen hastalık tanısıdır`},dogru:`C`,aciklama:`PGD IVF embriyolarının test edilip sağlıklısının transferidir, en önemli yararı medikal abortustan korumasıdır; PGS anöploidi taramasıyla öploid transferdir, ileri anne yaşında yaygındır.`,sik_aciklamalari:{A:`PGD tanısal, PGS taramadır.`,B:`PGS anöploidi tarar.`,C:`Doğru: iki kavramın endikasyon ve yarar ayrımı birlikte doğru.`,D:`En önemli yararı budur.`,E:`Mendeliyen tanı PGD'dir.`},bilgi:[1,2,3],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k01-q05`,kazanim:1,zorluk:`zor`,soru:`OR kalıtımlı hastalık taşıyıcısı çift, prenatal tanı yerine PGD istiyor. Laboratuvar tek hücreden hem mutasyon hem kromozom analizi öneriyor. Hangi gerekçe doğrudur?`,secenekler:{A:`Mendeliyen risk düşük olduğundan PGD gereksizdir`,B:`PGD bol materyal ve uzun süre gerektirir`,C:`NGS yalnızca anöploidiye bakar`,D:`Mikroarray FISH'ten önce gelir`,E:`OR hastalıkta %25 tekrarlama riski nedeniyle PGD prenatal tanıya üstündür; işlem tek-birkaç hücreyle kısa sürede tamamlanmalıdır; NGS anöploidi ve tek gen analizini aynı anda yapar`},dogru:`E`,aciklama:`Mendeliyen risk %25-50 olduğundan PGD'nin prenatal tanıya büyük avantajı vardır; PGD minimal materyal ve kısa süre gerektirir; teknoloji mikroarray ve NGS ile kombine analize evrilmiştir.`,sik_aciklamalari:{A:`Risk %25-50 ile yüksektir.`,B:`Minimal materyal ve kısa süre zorunludur.`,C:`NGS ikisini birlikte yapar.`,D:`Mikroarray FISH'in yerini almıştır.`,E:`Doğru: risk, zorunluluk ve teknoloji birlikte doğru.`},bilgi:[3,5],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k01-q06`,kazanim:1,zorluk:`orta`,soru:`PGD ve PGS tanımlarının farkı nedir?`,secenekler:{A:`PGD sağlıklı embriyo seçer; PGS anöploidi taramasıyla öploid transferi hedefler`,B:`PGD ve PGS aynı işlemdir`,C:`PGS tek gen hastalığı tanısıdır`,D:`PGD gebelik başarısını artırmaya yöneliktir`,E:`PGS hasta embriyo transferidir`},dogru:`A`,aciklama:`PGD yardımlı üremeyle elde edilen embriyoların laboratuvarda test edilip sağlıklı olanların transferidir; minimal materyal ve kısa süre zorunluluğu vardır. PGS ise tüp bebekte gebelik başarısını artırmak için aday embriyolarda anöploidi tarayıp öploid embriyonun transferidir.`,sik_aciklamalari:{A:`Doğru: PGD'nin tanı-seçim amacı ile PGS'nin tarama-başarı amacı doğru ayrılmıştır.`,B:`PGD tanı, PGS tarama uygulamasıdır.`,C:`Tek gen tanısı PGD kapsamındadır.`,D:`Gebelik başarısını artırma PGS tanımına aittir.`,E:`Her ikisinde de sağlıklı-öploid embriyo transfer edilir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k01-q07`,kazanim:1,zorluk:`orta`,soru:`PGD'nin prenatal tanıya avantajı ve tarihçesi nedir?`,secenekler:{A:`PGD tekrarlama riski düşükken tercih edilir`,B:`İlk PGD 1967'de yapılmıştır`,C:`Louise Brown ilk PGD bebeğidir`,D:`PGD yüksek tekrarlama riskinde avantajlıdır; ilk PGD 1989'da X hastalığındadır`,E:`Prenatal tanı PGD'den önce gelir`},dogru:`D`,aciklama:`PGD'nin prenatal tanıya avantajı Mendeliyen hastalıklardaki yüksek tekrarlama riskidir (%25-50). Tarihçede 1987 ilk tüp bebek (Louise Brown), 1989 ilk insan embriyo biyopsisi ve PGD (X'e bağlı hastalık), 1990 ilk sağlıklı PGD bebeğidir.`,sik_aciklamalari:{A:`%25-50 gibi yüksek tekrarlama riski PGD avantajıdır.`,B:`1967 tavşanda ilk embriyo biyopsisidir.`,C:`Louise Brown 1987'de ilk tüp bebektir.`,D:`Doğru: avantaj gerekçesi ve tarihçe birlikte doğru verilmiştir.`,E:`PGD gebelik oluşmadan seçim sağladığı için avantajlıdır.`},bilgi:[3,4],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`PGD/PGS endikasyonlarını ve hangi çiftlere uygulandığını sıralamak`,sorular:[{id:`k1-60-q04`,kazanim:2,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi PGD endikasyonu değildir?`,secenekler:{A:`Dengeli yapısal kromozom anomalisi taşıyıcılığı`,B:`Tek gen hastalığı taşıyıcısı çift`,C:`Genetik riski olmayan, doğal yolla ilk gebeliğini sorunsuz elde etmiş genç çift`,D:`İki veya daha fazla IVF başarısızlığı`,E:`HLA uyumlu kardeş isteyen çift`},dogru:`C`,aciklama:`PGD endikasyonları tek gen hastalığı riski, yapısal kromozom anomalisi, ileri yaş IVF, tekrarlayan IVF başarısızlığı ve HLA uyumlu kardeş isteğidir.`,sik_aciklamalari:{A:`Önemli endikasyondur.`,B:`Öncelikli endikasyondur.`,C:`Doğru: genetik risk ve IVF gereksinimi yoktur.`,D:`Endikasyondur: i̇ki veya daha fazla IVF başarısızlığı.`,E:`Endikasyondur: HLA uyumlu kardeş isteyen çift.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-60-q05`,kazanim:2,zorluk:`orta`,soru:`Mendelyen kalıtılan hastalıklarda PGD'nin prenatal tanıya göre büyük avantaj sağlamasının nedeni hangisidir?`,secenekler:{A:`PGD'nin maliyetinin daha düşük olması`,B:`Bu hastalıklarda tekrarlama riskinin sıfır olması`,C:`Prenatal tanının bu hastalıklarda hiç yapılamaması`,D:`PGD'nin IVF gerektirmemesi`,E:`Tekrarlama riskinin %25 veya %50 gibi yüksek olması ve gebelik terminasyonu ihtiyacının önlenmesi`},dogru:`E`,aciklama:`Yüksek tekrarlama riskli ailelerde PGD sağlıklı embriyo seçerek tekrar eden terminasyonları önler.`,sik_aciklamalari:{A:`PGD maliyetlidir: PGD'nin maliyetinin daha düşük olması.`,B:`Risk yüksektir: bu hastalıklarda tekrarlama riskinin sıfır olması.`,C:`Prenatal tanı yapılabilir; ancak sonlandırma gerektirebilir.`,D:`PGD IVF gerektirir: PGD'nin IVF gerektirmemesi.`,E:`Doğru: avantajın gerekçesidir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-60-q06`,kazanim:2,zorluk:`zor`,soru:`Konvansiyonel prenatal tanı yerine PGD'nin tercih edileceği durum aşağıdakilerden hangisidir?`,secenekler:{A:`Genetik riski olmayan rutin gebelik`,B:`Ciddi genetik riskli ailede gebelik sonlandırmanın etik/dini/kişisel nedenlerle kabul edilmediği veya geç kalacağı durum`,C:`Yalnızca folik asit eksikliği`,D:`Yalnızca fetal cinsiyet merakı`,E:`Gebeliğin üçüncü trimesterinde başvuru`},dogru:`B`,aciklama:`Konvansiyonel prenatal tanıyla sonlandırmanın geç kalacağı veya kabul edilmediği ciddi riskli ailelerde PGD tercih edilir.`,sik_aciklamalari:{A:`Risk yoksa PGD endikasyonu yoktur.`,B:`Doğru: PGD'nin klinik endikasyonudur.`,C:`Folik asit eksikliği PGD endikasyonu değildir.`,D:`Tıbbi gerekçe olmadan cinsiyet seçimi endikasyon değildir.`,E:`PGD gebelik başlamadan uygulanır.`},bilgi:[3,7],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k02-q04`,kazanim:2,zorluk:`orta`,soru:`Genetik konseyinde iki çift değerlendiriliyor: dengeli translokasyonlu ve tekrarlayan IVF başarısızlıklı çift ile hasta çocuğa donör arayan çift. Hangi endikasyon değerlendirmesi doğrudur?`,secenekler:{A:`PGD yalnızca infertil çiftlere yapılır`,B:`38 yaşındaki, iki IVF başarısızlıklı, dengeli translokasyonlu çift ile Fanconi anemili çocuğuna HLA uyumlu kardeş isteyen çift PGD adayıdır; mozaiklik ve mitokondriyal hastalıklarda uygulama zordur`,C:`HLA kardeş isteği endikasyon değildir`,D:`İleri anne yaşı endikasyon değildir`,E:`IVF başarısızlığı PGD'yi kontrendike eder`},dogru:`B`,aciklama:`Endikasyonlar: taşıyıcılık/hasta çocuk, >35 yaş IVF, ≥2 IVF başarısızlığı, yapısal anomali, HLA kardeş isteği; mozaiklik, mitokondriyal ve epigenetik durumlarda zordur.`,sik_aciklamalari:{A:`Genetik riskli fertil çiftler de adaydır.`,B:`Doğru: aday grupları ve zorluk alanları birlikte doğru.`,C:`HLA kardeş amaçlı endikasyondur.`,D:`>35 yaş endikasyondur.`,E:`≥2 başarısızlık endikasyondur.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Sınavda PGD tarihçesi kronolojik sıralanıyor ve HLA uygulamasının başlangıcı soruluyor. Hangi dizi doğrudur?`,secenekler:{A:`İlk insan PGD 1967'dedir`,B:`Louise Brown PGD bebeğidir`,C:`HLA tiplemesi PGD'den önce yapılmıştır`,D:`Tarihçe: 1967 tavşan biyopsisi, 1987 ilk tüp bebek, 1989 ilk insan PGD (X'e bağlı hastalık), 1990 ilk sağlıklı PGD bebeği; ilk HLA tiplemesi 2001'de Fanconi anemisi içindir`,E:`PGD yalnızca son 5 yıldır uygulanır`},dogru:`D`,aciklama:`1967 tavşan biyopsisi, 1987 Louise Brown, 1989 Handyside ilk insan PGD, 1990 ilk sağlıklı bebek; ilk HLA tiplemesi 2001 Verlinsky (Fanconi), ülkemizde Kahraman ve ark.`,sik_aciklamalari:{A:`1967 tavşan biyopsisidir.`,B:`Louise Brown ilk tüp bebektir.`,C:`HLA 2001'de yapılmıştır.`,D:`Doğru: kronoloji ve HLA başlangıcı birlikte doğru.`,E:`1990'dan beri uygulanır.`},bilgi:[4,21],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k02-q06`,kazanim:2,zorluk:`orta`,soru:`PGD/PGS endikasyonları hangileridir?`,secenekler:{A:`PGD yalnızca infertil çiftlere uygulanır`,B:`Taşıyıcılık, ileri yaş, IVF başarısızlığı ve translokasyon PGD endikasyonudur`,C:`HLA kardeş isteği endikasyon değildir`,D:`Tek IVF başarısızlığı yeterlidir`,E:`Otuz yaş altı tüm çiftler adaydır`},dogru:`B`,aciklama:`PGD endikasyonları tek gen taşıyıcılığı-hasta çocuk öyküsü, 35 yaş sonrası IVF, 2+ IVF başarısızlığı, yapısal kromozom anomalisi ve HLA uyumlu kardeş isteğidir. Fertilite amaçlı IVF çiftleri, konvansiyonel prenatal tanıyla sonlandırmanın geç kalacağı ciddi riskliler ve geç ortaya çıkan OD riskliler de adaydır.`,sik_aciklamalari:{A:`Genetik riskli fertil çiftler de endikasyon kapsamındadır.`,B:`Doğru: dört endikasyon grubu birlikte doğru verilmiştir.`,C:`HLA uyumlu kardeş isteyen çiftler endikasyondur.`,D:`Eşik 2 veya daha fazla IVF başarısızlığıdır.`,E:`35 yaşından sonra IVF'e başvuranlar endikasyondur.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Yapısal anomalilerde endikasyon ve güncel teknoloji nedir?`,secenekler:{A:`Translokasyon taşıyıcılığı endikasyon değildir`,B:`Tekrarlayan kayıplarda PGD yapılmaz`,C:`FISH günümüzde tek yöntemdir`,D:`NGS yalnızca anöploidi bakar`,E:`Yapısal anomaliler ve kayıplar endikasyondur; NGS ikili tanı sağlar`},dogru:`E`,aciklama:`Translokasyon-inversiyon taşıyıcılarında erkek infertilitesi, tekrarlayan gebelik kayıpları ve ileri maternal yaş PGD gerektirir. Mikroarray FISH'in yerini almış, PCR tabanlı analizler ve NGS ile anöploidi taramasıyla tek gen tanısı aynı anda yapılabilir hale gelmiştir.`,sik_aciklamalari:{A:`Translokasyon-inversiyon taşıyıcıları endikasyondur.`,B:`Tekrarlayan gebelik kayıpları endikasyondur.`,C:`Mikroarray FISH'in yerini almıştır.`,D:`NGS ile anöploidi ve tek gen tanısı aynı anda yapılır.`,E:`Doğru: endikasyon ve teknolojik gelişme birlikte doğru verilmiştir.`},bilgi:[5,7],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:3,metin:`Kromozomal (sayısal ve yapısal) düzensizliklerde PGD uygulamasını ve segregasyon tiplerini tanımlamak`,sorular:[{id:`k1-60-q07`,kazanim:3,zorluk:`kolay`,soru:`Dengeli translokasyon taşıyıcısında dengeli gamet oluşturan segregasyon tipi hangisidir?`,secenekler:{A:`3:1 interchange segregasyon`,B:`Adjacent-1 segregasyon`,C:`Adjacent-2 segregasyon`,D:`Alternate segregasyon`,E:`3:1 tersiyer segregasyon`},dogru:`D`,aciklama:`Alternate segregasyon dengeli, adjacent-1 ve adjacent-2 dengesiz gamet/embriyo verir.`,sik_aciklamalari:{A:`3:1 interchange tam trizomi/monozomi yapar.`,B:`Adjacent-1 dengesiz ürün verir.`,C:`Adjacent-2 dengesiz ürün verir.`,D:`Doğru: alternate segregasyon dengeli ürün verir.`,E:`3:1 tersiyer segregasyon dengesiz ürün verir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-60-q08`,kazanim:3,zorluk:`orta`,soru:`Dengeli translokasyon taşıyıcılığının görülme sıklığı en yüksek olan grup hangisidir?`,secenekler:{A:`Sağlıklı çocuk sahibi çiftler`,B:`Neonatal popülasyon (~%0,2)`,C:`İnfertil çiftler (~%0,6)`,D:`Genel erişkin popülasyon`,E:`İlk trimester gebelik kayıpları (~%6)`},dogru:`E`,aciklama:`Taşıyıcılık neonatal popülasyonda %0,2, infertil çiftlerde %0,6, ilk trimester kayıplarında %6'dır.`,sik_aciklamalari:{A:`Bu grupta yüksek değildir.`,B:`Neonatal popülasyonda düşüktür.`,C:`İnfertil çiftlerde orta düzeydedir.`,D:`Genel popülasyonda düşüktür.`,E:`Doğru: en yüksek oran kayıplardadır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-60-q09`,kazanim:3,zorluk:`zor`,soru:`Anöploidiler ile ilgili hangisi doğrudur?`,secenekler:{A:`Kromozomun bir parçasının kaybıdır`,B:`Genellikle paternal mayoz II hatasından kaynaklanır`,C:`Genellikle maternal mayoz I hatalarından kaynaklanır ve ileri maternal yaş, tekrarlayan IVF başarısızlığı ve ilk trimester kayıplarının önemli nedenidir`,D:`PGS ile araştırılamaz`,E:`Gebelik kayıplarıyla ilişkisi yoktur`},dogru:`C`,aciklama:`Anöploidiler bir kromozomun tamamını içeren sayısal bozukluklardır; PGS ile taranır.`,sik_aciklamalari:{A:`Parça kaybı yapısal anomalidir.`,B:`Çoğunlukla maternal mayoz I kaynaklıdır.`,C:`Doğru: anöploidilerin kaynağı ve klinik önemi doğrudur.`,D:`PGS anöploidi taramasıdır.`,E:`İlk trimester kayıplarının önemli nedenidir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k03-q04`,kazanim:3,zorluk:`orta`,soru:`Üç kez ilk trimester kaybı yaşayan çiftte karyotipte dengeli translokasyon saptanıyor. Danışmanlıkta sıklık ve anöploidi kökeni anlatılıyor. Hangi açıklama doğrudur?`,secenekler:{A:`Tekrarlayan ilk trimester kayıplı çiftte dengeli translokasyon akla gelmelidir (kayıplarda taşıyıcılık %6); anöploidiler genellikle maternal mayoz 1 hatasıdır ve PGS ile araştırılır; Robertsonian translokasyon akrosentrik kromozomlar arasındadır`,B:`Anöploidiler paternal mitoz hatasıdır`,C:`Translokasyon taşıyıcılığı kayıplarda %0,2'dir`,D:`Robertsonian aynı kromozomun duplikasyonudur`,E:`Sayısal anomaliler PGT-M ile araştırılır`},dogru:`A`,aciklama:`Anöploidiler maternal mayoz 1 hatasıdır, PGS ile araştırılır; resiprokal karşılıklı değişim, Robertsonian akrosentrikler arasıdır; taşıyıcılık neonatal %0,2, infertil %0,6, ilk trimester kaybı %6'dır.`,sik_aciklamalari:{A:`Doğru: sıklık, köken ve yöntem birlikte doğru.`,B:`Genellikle maternal mayoz 1'dir.`,C:`Kayıplarda %6'dır.`,D:`İki akrosentrik arası translokasyondur.`,E:`Sayısal anomaliler PGS/PGT-A ile araştırılır.`},bilgi:[8,9,10,11],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k03-q05`,kazanim:3,zorluk:`zor`,soru:`Dengeli resiprokal translokasyon taşıyıcısı çiftin PGD raporunda bazı embriyolar dengeli, bazıları dengesiz bulunuyor. Embriyolog segregasyonu açıklıyor. Hangi açıklama doğrudur?`,secenekler:{A:`Adjacent segregasyon dengeli ürün verir`,B:`Alternate dengesiz ürün verir`,C:`Resiprokal translokasyonlu çiftin embriyolarında alternate segregasyon dengeli, adjacent-1/2 dengesiz ürün verir; 3:1 segregasyon full trizomi-monozomiye yol açar ve dengesiz embriyo oranı %20-100'dür`,D:`Tüm embriyolar dengelidir`,E:`Segregasyon embriyo dengesini belirlemez`},dogru:`C`,aciklama:`Alternate dengeli, adjacent-1/2 dengesiz ürün verir; 3:1 interchange/tersiyer full trizomi-monozomi yapar; dengesiz embriyo oranı %20-100'dür.`,sik_aciklamalari:{A:`Adjacent dengesizdir.`,B:`Alternate dengelidir.`,C:`Doğru: segregasyon-sonuç ilişkisi ve oran birlikte doğru.`,D:`%20-100 dengesizdir.`,E:`Segregasyon tipi belirleyicidir.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Sayısal ve yapısal kromozom düzensizlikleri nasıl ayrılır?`,secenekler:{A:`Anöploidi sayısal mayoz 1 hatasıdır; yapısal anomaliler translokasyon ve inversiyonlardır`,B:`Anöploidi yapısal bozukluktur`,C:`Mayoz 1 hatası yapısal anomali yapar`,D:`Translokasyonlar kayıplarla ilişkisizdir`,E:`Anöploidi PGD ile değil yalnızca karyotiple bakılır`},dogru:`A`,aciklama:`Anöploidiler bir kromozomun tamamını içeren sayısal bozukluklardır, genellikle maternal mayoz 1 hatasından kaynaklanır ve PGS ile araştırılır. Yapısal anomaliler dengeli translokasyon, insersiyon, inversiyon, delesyon ve duplikasyondur; dengeli translokasyonlar tekrarlayan kayıpların önemli nedenidir.`,sik_aciklamalari:{A:`Doğru: sayısal-yapısal ayrımı ve köken birlikte doğru verilmiştir.`,B:`Anöploidi tüm kromozomu içeren sayısal bozukluktur.`,C:`Sayısal bozukluklar maternal mayoz 1 hatalarındandır.`,D:`Dengeli translokasyonlar tekrarlayan kayıpların önemli nedenidir.`,E:`Anöploidiler PGS yöntemiyle araştırılır.`},bilgi:[8,9,10],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Translokasyon tipleri ve segregasyon sonuçları nelerdir?`,secenekler:{A:`Robertsonian aynı kromozomda parça değişimidir`,B:`Adjacent segregasyon dengeli ürün verir`,C:`Alternate dengeli, adjacent dengesiz ürün verir`,D:`Taşıyıcılık kayıplarda %0,2'dir`,E:`3:1 segregasyon en sık olandır`},dogru:`C`,aciklama:`Resiprokal translokasyon karşılıklı parça değişimi, Robertsonian iki akrosentrik kromozom arası translokasyondur; taşıyıcılık infertil çiftlerde %0,6, ilk trimester kayıplarında %6'dır. Alternate segregasyon dengeli, adjacent-1 ve adjacent-2 dengesiz ürün verir.`,sik_aciklamalari:{A:`Robertsonian iki akrosentrik kromozom arasındadır.`,B:`Adjacent-1 ve adjacent-2 dengesiz gamet-embriyo verir.`,C:`Doğru: segregasyon tiplerinin sonuçları doğru karşılaştırılmıştır.`,D:`İlk trimester kayıplarında taşıyıcılık %6'dır.`,E:`3:1 interchange ve tersiyer segregasyona daha az rastlanır.`},bilgi:[11,12],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Tek gen hastalıklarında (OR, OD, XR) ve HLA uyumlu kardeş amaçlı PGD ilkelerini bilmek`,sorular:[{id:`k1-60-q10`,kazanim:4,zorluk:`kolay`,soru:`Otozomal resesif hastalık için heterozigot taşıyıcı iki ebeveynin çocuğunun hasta olma riski nedir?`,secenekler:{A:`%50`,B:`%25`,C:`%75`,D:`%100`,E:`%0`},dogru:`B`,aciklama:`OR kalıtımda heterozigot çiftin çocuğunda hastalık %25, taşıyıcılık %50, sağlıklı %25 olasılıktır.`,sik_aciklamalari:{A:`%50 taşıyıcılık riskidir.`,B:`Doğru: OR hastalık riskidir.`,C:`%75 sağlıklı veya taşıyıcı toplamıdır.`,D:`%100 değildir: %100.`,E:`Risk vardır: %0; bu nedenle doğru seçenek değildir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-60-q11`,kazanim:4,zorluk:`orta`,soru:`HLA uyumlu kardeş amaçlı PGD'nin temel gerekçesi hangisidir?`,secenekler:{A:`Hasta çocuğun gen tedavisine ihtiyaç duymaması`,B:`HLA genlerinin X kromozomunda bulunması`,C:`HLA uyumunun IVF başarısını garanti etmesi`,D:`Beta talasemi gibi hastalıklarda en iyi tedavi olan allojenik kök hücre naklinde tam HLA uyumlu kardeş vericinin en iyi sonucu vermesi`,E:`HLA tiplemesinin kolay ve ucuz olması`},dogru:`D`,aciklama:`HLA genleri 6p'de yer alır; uygun donör yoksa hem mutasyon açısından normal hem HLA uyumlu embriyo seçilir.`,sik_aciklamalari:{A:`Amaç kök hücre nakli için verici sağlamaktır.`,B:`HLA genleri 6. kromozomun kısa kolundadır.`,C:`HLA uyumu IVF başarısını belirlemez.`,D:`Doğru: HLA PGD'nin gerekçesidir.`,E:`Maliyet yüksektir: HLA tiplemesinin kolay ve ucuz olması.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-60-q13`,kazanim:4,zorluk:`orta`,soru:`HLA uyumlu kardeş amaçlı PGD'de en büyük zorluk hangisidir?`,secenekler:{A:`Embriyo sayısının fazla olması`,B:`ICSI'nin gereksiz olması`,C:`Maliyetin çok düşük olması`,D:`Hem HLA uyumlu hem mutasyon açısından normal embriyo bulma olasılığının düşük olması`,E:`HLA genlerinin tek kromozomda olmaması`},dogru:`D`,aciklama:`İki koşulu birlikte sağlayan embriyo olasılığı düşüktür; az embriyo, öngörülemeyen yanıt, yüksek maliyet ve kontaminasyon için ICSI zorunluluğu diğer zorluklardır.`,sik_aciklamalari:{A:`Embriyo sayısı azdır.`,B:`Kontaminasyonu önlemek için ICSI zorunludur.`,C:`Maliyet yüksektir: maliyetin çok düşük olması.`,D:`Doğru: en büyük sıkıntıdır.`,E:`HLA genlerinin çoğu 6p'dedir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-60-q12`,kazanim:4,zorluk:`zor`,soru:`Huntington hastalığı riski taşıyan ancak kendi taşıyıcılık durumunu öğrenmek istemeyen birey için PGD'de uygulanan yaklaşım hangisidir?`,secenekler:{A:`PGD'nin kesinlikle reddedilmesi`,B:`Bireyin isteğine rağmen sonucunun açıklanması`,C:`Ebeveyn taraması yapılmadan ve raporlanmadan hastalıksız embriyoların transferi`,D:`Tüm embriyoların test edilmeden transferi`,E:`Yalnızca erkek embriyoların transferi`},dogru:`C`,aciklama:`Huntington'da çoğu çift kendi durumunu bilmek istemez; ebeveyn sonucu raporlanmadan hastalıksız embriyolar transfer edilir.`,sik_aciklamalari:{A:`PGD uygulanabilir: PGD'nin kesinlikle reddedilmesi.`,B:`Bilmeme hakkı ihlal edilir.`,C:`Doğru: bilmeme hakkını koruyan yaklaşımdır.`,D:`Test edilmeden transfer PGD amacına aykırıdır.`,E:`OD hastalıkta cinsiyet seçimi anlamsızdır.`},bilgi:[16,17],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k04-q05`,kazanim:4,zorluk:`orta`,soru:`Üç çift danışmanlıkta: talasemi taşıyıcısı çift, Huntington hastası ebeveyn ve hemofili taşıyıcısı kadın. Riskler karşılaştırılıyor. Hangi tablo doğrudur?`,secenekler:{A:`OR'de hasta riski %50'dir`,B:`OD'de atlama kuşaklar tipiktir`,C:`XR'de kızlar hemizigottur`,D:`OR yatay değil dikey paternlidir`,E:`Talasemi taşıyıcısı çiftte her gebelikte %25 hasta riski (yatay patern); Huntingtonlı ebeveynde %50 risk (dikey patern); hemofili taşıyıcısında erkeklerin %50'si hasta, kızların %50'si taşıyıcıdır`},dogru:`E`,aciklama:`OR'de heterozigot ebeveynden hasta %25, taşıyıcı %50, sağlıklı %25; OD'de her gebelik %50, dikey patern; XR'de kadın taşıyıcı, erkek hemizigot hastadır.`,sik_aciklamalari:{A:`Hasta %25, taşıyıcı %50'dir.`,B:`OD dikey paternlidir.`,C:`Erkekler hemizigottur.`,D:`OR yatay paternlidir.`,E:`Doğru: üç kalıtımın risk ve patern üçlüsü tamdır.`},bilgi:[13,16,18,19],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k04-q06`,kazanim:4,zorluk:`zor`,soru:`Beta talasemili ve HLA uyumsuz çocuğu olan çift, hasta çocuğa kök hücre için uyumlu kardeş istiyor. Laboratuvar kombine PGD planlıyor. Hangi açıklama doğrudur?`,secenekler:{A:`HLA genleri X kromozomundadır`,B:`Talasemili çocuğa donör arayan çiftte HLA genleri (6. kromozom kısa kolu) ile mutasyon birlikte analiz edilir; en büyük zorluk hem uyumlu hem sağlıklı embriyo olasılığının düşüklüğüdür ve ICSI ile kontaminasyon önlenir; ADO güvenilirliği bozar`,C:`HLA PGD'de embriyo sayısı başarıyı etkilemez`,D:`Kontaminasyon PGD'de önemsizdir`,E:`ADO güvenilirliği artırır`},dogru:`B`,aciklama:`HLA genleri 6. kromozom kısa kolunda; zorluk uyumlu+normal embriyo olasılığının düşüklüğü, az embriyo, maliyet, ICSI zorunluluğudur; güvenilirlikte ADO, kontaminasyon ve amplifikasyon kaybı riski vardır.`,sik_aciklamalari:{A:`6. kromozom kısa kolundadır.`,B:`Doğru: lokus, zorluk ve kalite üçlüsü birlikte doğru.`,C:`Az embriyo gebelik şansını azaltır.`,D:`ICSI kontaminasyonu önlemek için zorunludur.`,E:`ADO allel kaybıyla yanıltır.`},bilgi:[20,21,22],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k04-q07`,kazanim:4,zorluk:`orta`,soru:`OD ve OR kalıtımda PGD risk ilkeleri nelerdir?`,secenekler:{A:`OD kalıtımda risk %25'tir`,B:`OD'de %50 dikey, OR'da %25 yatay risk vardır`,C:`OR kalıtım her kuşakta görülür`,D:`Akrabalık OR riskini azaltır`,E:`OD kalıtım yatay patern izler`},dogru:`B`,aciklama:`OD kalıtımda hasta kişinin her gebelikte çocuk riski %50'dir, dikey patern izlenir. OR kalıtımda yatay patern izlenir; heterozigot ebeveynlerde hasta %25, taşıyıcı %50, sağlıklı %25 çocuk olur ve akraba evliliğinde risk artar.`,sik_aciklamalari:{A:`OD'de hasta kişinin çocuklarında her gebelikte %50 risk vardır.`,B:`Doğru: iki kalıtımın risk ve paterni doğru karşılaştırılmıştır.`,C:`OR her kuşakta kendini göstermez.`,D:`Akraba evliliklerinde OR riski artar.`,E:`OD Mendelyen dikey patern izler.`},bilgi:[16,18],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k04-q08`,kazanim:4,zorluk:`orta`,soru:`X'e bağlı kalıtım ve HLA amaçlı PGD ilkeleri nelerdir?`,secenekler:{A:`X kalıtımda erkekler taşıyıcıdır`,B:`Kız çocuklar hasta olmaz`,C:`HLA genleri 12. kromozomdadır`,D:`X'te erkek hasta olur; HLA nakilde en iyisidir`,E:`HLA PGD'de embriyo bulmak kolaydır`},dogru:`D`,aciklama:`X'e bağlı kalıtımda kadınlar taşıyıcı, erkekler hemizigot hastadır; kızların %50'si taşıyıcı, erkeklerin %50'si hasta olur, X inaktivasyonuyla kızlarda da hastalık görülebilir. HLA genleri 6. kromozom kısa kolundadır; talasemi ve lösemilerde en iyi sonuç tam uyumlu kardeş vericidendir.`,sik_aciklamalari:{A:`Erkekler hemizigot ve hastadır.`,B:`X inaktivasyonuna bağlı kızlarda da hastalık görülebilir.`,C:`HLA genlerinin çoğu 6. kromozom kısa kolundadır.`,D:`Doğru: X kalıtım kuralı ve HLA amacı birlikte doğru verilmiştir.`,E:`Hem uyumlu hem normal embriyo bulma olasılığı düşüktür.`},bilgi:[19,20],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:5,metin:`STR tabanlı haplotipleme ve SNP tabanlı Karyomapping yöntemlerini karşılaştırmak`,sorular:[{id:`k1-60-q14`,kazanim:5,zorluk:`kolay`,soru:`Mutasyonun doğrudan analizi yapılmadan, hastalık genine komşu STR alelleri izlenerek yapılan PGD yöntemi hangisidir?`,secenekler:{A:`FISH`,B:`STR tabanlı haplotipleme (PGH)`,C:`a-CGH`,D:`Sanger dizileme`,E:`Karyotip`},dogru:`B`,aciklama:`STR tabanlı haplotiplemede gen bölgesine komşu aleller izlenerek riskli kromozom bölgesinin aktarılıp aktarılmadığı belirlenir.`,sik_aciklamalari:{A:`FISH prob hibridizasyonudur.`,B:`Doğru: haplotiplemenin tanımıdır.`,C:`a-CGH dozaj farkını saptar.`,D:`Sanger doğrudan mutasyon dizilemesidir.`,E:`Karyotip kromozom yapısını inceler.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-60-q15`,kazanim:5,zorluk:`orta`,soru:`SNP tabanlı Karyomapping yönteminin STR haplotiplemeye üstünlüğü hangisidir?`,secenekler:{A:`Rekombinasyon hata payının artması`,B:`Yalnızca tek bir STR bölgesini incelemesi`,C:`Hiç linkage analizi yapmaması`,D:`Sadece sayısal anomalileri göstermesi`,E:`Tüm genom boyunca ~300.000 SNP ile linkage analizi yapması ve teorik olarak tüm kalıtsal hastalıklara uygulanabilmesi`},dogru:`E`,aciklama:`Karyomapping genom boyunca homojen dağılmış SNP'lerle analiz yapar; rekombinasyon hata payı azalır.`,sik_aciklamalari:{A:`Hata payı azalır: rekombinasyon hata payının artması.`,B:`Tüm genom incelenir.`,C:`Genom boyu linkage analizi yapar.`,D:`Monogenik hastalıklar da değerlendirilebilir.`,E:`Doğru: yöntemin üstünlüğüdür.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-60-q16`,kazanim:5,zorluk:`zor`,soru:`Mutasyon spesifik test imkânı olmayan bir tek gen hastalığında PGD için en uygun yaklaşım hangisidir?`,secenekler:{A:`Yalnızca morfolojik embriyo seçimi`,B:`Yalnızca FISH ile sayısal analiz`,C:`Yalnızca a-CGH`,D:`PGD yapılamaz`,E:`Hastalık genine bağlı marker/haplotip analizi (STR veya SNP tabanlı)`},dogru:`E`,aciklama:`Mutasyon spesifik test olmadığında bağlantı analizi (haplotipleme/Karyomapping) etkilidir.`,sik_aciklamalari:{A:`Morfoloji genetik durumu göstermez.`,B:`FISH tek gen mutasyonunu göstermez.`,C:`a-CGH dozaj analizidir.`,D:`Haplotipleme ile PGD yapılabilir.`,E:`Doğru: dolaylı bağlantı analizi uygundur.`},bilgi:[14,15],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k05-q04`,kazanim:5,zorluk:`orta`,soru:`Mutasyonu tanımlanamamış tek gen hastalıklı ailenin PGD'sinde strateji tartışılıyor. Akraba evliliği de mevcut. Hangi yöntem açıklaması doğrudur?`,secenekler:{A:`PGH mutasyonu doğrudan sekanslar`,B:`PGH için 2 STR yeterlidir`,C:`Karyomapping hastaya özel dizayn gerektirir`,D:`Mutasyonu bilinmeyen tek gen hastalığında gene komşu en az 8 STR izlenir (akraba evliliği bilgilendiriciliği azaltır); SNP tabanlı karyomapping 300.000 SNP ile tüm genomda linkage yapar ve ön dizayn gerektirmez`,E:`Karyomapping yalnız tek kromozoma bakar`},dogru:`D`,aciklama:`PGH mutasyona bakmadan komşu STR izler, en az 8 STR, yalnız tek gen hastalıklarında, akraba evliliği olumsuz etkiler; Karyomapping SNP ile tüm genom linkage yapar, dizayn gerekmez.`,sik_aciklamalari:{A:`Mutasyona bakılmadan komşu allel izlenir.`,B:`En az 8 STR gerekir.`,C:`Dizayn gerekmez.`,D:`Doğru: iki yöntemin mantık ve koşul farkı birlikte doğru.`,E:`Tüm genom analiz edilir.`},bilgi:[14,15],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Huntington riski taşıyan ancak kendi durumunu öğrenmek istemeyen bireyin PGD'sinde etik ve teknik strateji tartışılıyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`Karyomappingin üstünlüğü SNP'lerin homojen dağılımı ve rekombinasyon hata payının azalmasıdır; STR'de markerler gene yakın ve bilgilendirici olmalıdır; Huntington gibi OD hastalıkta ebeveyn taranmadan hastalıksız embriyo seçimi etik çözümdür`,B:`STR rekombinasyondan etkilenmez`,C:`Huntingtonda ebeveyn testi zorunludur`,D:`Penetrans danışmanlığı etkilemez`,E:`Gonadal mozaiklik OD'de önemsizdir`},dogru:`A`,aciklama:`SNP'ler sık-homojen dağılır, rekombinasyon hatası azalır; STR'de yakın-bilgilendirici marker ve yeterli sayı gerekir; OD'de penetrans-ekspressivite ve gonadal mozaiklik danışmanlığı zorlaştırır.`,sik_aciklamalari:{A:`Doğru: teknik üstünlük ve OD etik yaklaşımı birlikte doğru.`,B:`Rekombinasyon STR'de hata kaynağıdır.`,C:`Ebeveyn taranmadan seçim yapılabilir.`,D:`Penetrans-ekspressivite danışmanlığı zorlaştırır.`,E:`Gonadal mozaiklik dikkate alınır.`},bilgi:[15,16,32],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k05-q06`,kazanim:5,zorluk:`orta`,soru:`STR haplotipleme ve Karyomapping nasıl ayrılır?`,secenekler:{A:`STR komşu allel izler; Karyomapping tüm genom SNP bakar`,B:`STR mutasyonu doğrudan saptar`,C:`Karyomapping tek gene özgüdür`,D:`STR tüm genomu tarar`,E:`İkisi de mutasyon gerektirmez ve aynıdır`},dogru:`A`,aciklama:`STR haplotiplemede mutasyon analizi yapılmadan gene komşu alleller izlenerek referans kişiden aktarım kontrol edilir. Karyomappingde tüm genomda ~300.000 SNP ile linkage analizi yapılır ve teorik olarak kalıtılan tüm hastalıklara uygundur.`,sik_aciklamalari:{A:`Doğru: iki yöntemin kapsam ve strateji farkı doğru karşılaştırılmıştır.`,B:`STR'de mutasyon analizi yapılmaz, haplotip izlenir.`,C:`Karyomapping tüm genom linkage analizidir.`,D:`Tüm genom SNP yaklaşımı Karyomapping'e aittir.`,E:`STR hedef bölgeye, Karyomapping genoma yöneliktir.`},bilgi:[14,15],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Huntington etiği ve HLA PGD zorlukları nelerdir?`,secenekler:{A:`Huntington'da ebeveyn testi zorunludur`,B:`HLA PGD'de ICSI gerekmez`,C:`Huntington'da ebeveynsiz seçim yapılır; HLA'da ICSI zorunludur`,D:`HLA PGD'de gebelik şansı yüksektir`,E:`Maliyet HLA PGD'de düşüktür`},dogru:`C`,aciklama:`Huntington'da çoğu çift kendi durumunu bilmek istemez; ebeveyn taraması yapılmadan hastalıksız embriyolar seçilip transfer edilir. HLA PGD'de az embriyo, öngörülemez indüksiyon yanıtı ve kontaminasyon riski nedeniyle ICSI zorunludur.`,sik_aciklamalari:{A:`Ebeveyn taraması yapılmadan raporlanmadan seçim yapılır.`,B:`Kontaminasyonu önlemek için ICSI zorunludur.`,C:`Doğru: iki durumun etik-teknik ilkesi birlikte doğru verilmiştir.`,D:`Az embriyo nedeniyle gebelik şansı azalır.`,E:`Maliyet yüksektir.`},bilgi:[17,21],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Embriyo biyopsi yöntemlerini (polar cisim, blastomer, trofoektoderm) avantaj ve dezavantajlarıyla karşılaştırmak`,sorular:[{id:`k1-60-q17`,kazanim:6,zorluk:`kolay`,soru:`Günümüzde PGD'de en çok tercih edilen embriyo biyopsi yöntemi hangisidir?`,secenekler:{A:`Blastomer biyopsisi`,B:`Polar cisim biyopsisi`,C:`Blastokist (trofoektoderm) biyopsisi`,D:`Koryon villus örneklemesi`,E:`Amniyosentez`},dogru:`C`,aciklama:`Blastomer biyopsisi eskiden en çok kullanılırken yerini 4–5. günde yapılan trofoektoderm biyopsisine bırakmıştır.`,sik_aciklamalari:{A:`Blastomer biyopsisi yerini blastokist biyopsisine bırakmıştır.`,B:`Polar cisim biyopsisi yalnız maternal riskleri gösterir.`,C:`Doğru: güncel tercih edilen yöntemdir.`,D:`CVS prenatal tanı yöntemidir.`,E:`Amniyosentez prenatal tanı yöntemidir.`},bilgi:[25,26],benzer_cikmis:[]},{id:`k1-60-q18`,kazanim:6,zorluk:`orta`,soru:`Polar cisim biyopsisinin kısıtlılığı aşağıdakilerden hangisidir?`,secenekler:{A:`Transferden önce analiz süresinin çok kısa olması`,B:`Paternal ve mitotik kaynaklı anöploidileri saptayamaması ve cinsiyet tayininde kullanılamaması`,C:`Embriyonun kritik hücrelerinin alınması`,D:`Her iki ebeveyn kaynaklı sorunları göstermesi`,E:`5. günde yapılması`},dogru:`B`,aciklama:`Polar cisim yalnız maternal genetik bilgiyi yansıtır; avantajı transferden önce uzun analiz süresidir.`,sik_aciklamalari:{A:`Avantajı uzun analiz süresidir.`,B:`Doğru: temel kısıtlılıktır.`,C:`Polar cisim embriyonun parçası değildir.`,D:`Yalnız maternal riskleri gösterir.`,E:`Oosit/zigot aşamasında yapılır.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-60-q19`,kazanim:6,zorluk:`zor`,soru:`Embriyo biyopsi yöntemleri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Blastomer biyopsisi 3. günde 6–8 hücreli aşamada yapılır`,B:`Trofoektoderm biyopsisinde tek seferde birkaç hücre alınabilir`,C:`Trofoektoderm plasentayı oluşturduğundan embriyonun kritik hücreleri alınmaz`,D:`Blastokist biyopsisinin dezavantajı zaman sorunu ve embriyo dondurma gerekliliğidir`,E:`Polar cisim biyopsisi babadan gelen mutasyonları saptamak için en uygun yöntemdir`},dogru:`E`,aciklama:`Polar cisim yalnız maternal genetik bilgiyi taşır; paternal mutasyonları gösteremez.`,sik_aciklamalari:{A:`Doğru ifade: blastomer biyopsisi 3. günde 6–8 hücreli aşamada yapılır.`,B:`Doğru ifade: 2–9 hücre alınabilir.`,C:`Doğru ifade: trofoektoderm plasentayı oluşturduğundan embriyonun kritik hücreleri alınmaz.`,D:`Doğru ifade: blastokist biyopsisinin dezavantajı zaman sorunu ve embriyo dondurma gerekliliğidir.`,E:`Yanlış ifade (aranan cevap): paternal mutasyonları saptayamaz.`},bilgi:[24,25,26],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k06-q04`,kazanim:6,zorluk:`orta`,soru:`Maternal yapısal anomalili çiftte biyopsi zamanlaması tartışılıyor. Polar cisim öneren ve karşı çıkan görüşler değerlendiriliyor. Hangi değerlendirme doğrudur?`,secenekler:{A:`Polar cisim paternal anomaliyi saptar`,B:`Polar cisim cinsiyet tayininde kullanılır`,C:`Maternal translokasyonlu çiftte polar cisim biyopsisi (metafaz II/2PN) uzun analiz süresi sağlar ancak paternal-mitotik anöploidiyi kaçırır ve cinsiyet tayininde kullanılamaz; bu yüzden günümüzde nadiren tercih edilir`,D:`Polar cisim her ebeveyn riskinde yeterlidir`,E:`Polar cisim en sık kullanılan yöntemdir`},dogru:`C`,aciklama:`Polar cisim metafaz II/2PN'den alınır, uzun analiz süresi avantajdır; paternal-mitotik anöploidiyi saptayamaz, cinsiyet tayininde kullanılamaz, yalnız anne riskinde ve nadiren tercih edilir.`,sik_aciklamalari:{A:`Paternal-mitotik kaynak saptanamaz.`,B:`Cinsiyet tayininde kullanılamaz.`,C:`Doğru: zamanlama, kısıt ve kullanım alanı birlikte doğru.`,D:`Yalnız anne kaynaklı risklerdedir.`,E:`Yerini blastokiste bırakmıştır.`},bilgi:[23,24],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k06-q05`,kazanim:6,zorluk:`zor`,soru:`Laboratuvar blastomerden trofoektoderme geçişi tartışıyor. Her yöntemin verdiği bilgi ve embriyoya etkisi karşılaştırılıyor. Hangi karşılaştırma doğrudur?`,secenekler:{A:`Blastomer yalnızca maternal riskte kullanılır`,B:`Trofoektoderm fetüsün kendisinden alınır`,C:`Blastokist biyopsisi implantasyonu azaltır`,D:`Trofoektoderm tek hücre verir`,E:`Blastomer biyopsisi 3. günde (6-8 hücre) her iki ebeveyn riskinde bilgi verir; trofoektoderm 4-5. günde plasentayı oluşturacak hücrelerden 6-7 hücre alınmasını sağlar ve embriyonun kritik hücreleri korunur; dezavantajı zaman baskısı ve dondurma gereğidir`},dogru:`E`,aciklama:`Blastomer 3. gün 6-8 hücrede her iki ebeveyn riskinde bilgi verir; trofoektoderm 4-5. günde 6-7 hücreyle plasentadan alınır, kritik hücre korunur; dezavantaj zaman-dondurma gereğidir.`,sik_aciklamalari:{A:`Her iki ebeveyn riskinde uygulanabilir.`,B:`Plasentayı oluşturacak hücrelerdendir.`,C:`Blastosiste ulaşanlar yüksek implantasyonludur.`,D:`Birkaç hücre (6-7) alınır.`,E:`Doğru: iki yöntemin zaman-kaynak-avantaj üçlüsü tamdır.`},bilgi:[25,26],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Polar cisim biyopsisinin avantaj ve kısıtlılığı nedir?`,secenekler:{A:`Polar cisim paternal bilgi verir`,B:`Polar cisim uzun analiz süresi sağlar ancak yalnızca maternaldir`,C:`Polar cisim 5. günde alınır`,D:`İki yöntem vardır`,E:`Polar cisim embriyodan alınır`},dogru:`B`,aciklama:`Üç biyopsi yöntemi polar cisim, blastomer ve trofoektodermdir. Polar cisimde 1. cisim metafaz II oositten, 2. cisim 2PN oositten alınır; avantajı transfer öncesi uzun analiz süresidir ancak yalnızca maternal bilgi verir.`,sik_aciklamalari:{A:`Polar cisimler oositten alınır, maternal bilgi verir.`,B:`Doğru: polar cisim zamanlaması, avantajı ve kısıtlılığı birlikte doğrudur.`,C:`Beşinci gün trofoektoderm biyopsisidir.`,D:`Üç temel yöntem vardır.`,E:`Embriyonun kendisi blastomer biyopsisinde örneklenir.`},bilgi:[23,24],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Blastomer ve trofoektoderm biyopsisi nasıl ayrılır?`,secenekler:{A:`Blastomer 5. günde alınır`,B:`Trofoektoderm tek hücre verir`,C:`Blastomer yalnızca maternal bilgi verir`,D:`Blastomer 3. günde embriyoyu, trofoektoderm 5. günde plasenta taslağını örnekler`,E:`Trofoektoderm kritik hücreleri alır`},dogru:`D`,aciklama:`Blastomer biyopsisi 3. günde 6-8 hücreli embriyoda yapılır, embriyonun kendisi hakkında bilgi verir ve her iki ebeveyn sorununda uygulanabilir. Trofoektoderm biyopsisi 4-5. günde yapılır; 2-9 hücre alınabilir, tekniktir kolaydır ve plasentayı oluşturacak hücreler alındığından kritik hücreler korunur.`,sik_aciklamalari:{A:`Blastomer 68-72. saatlerde alınır.`,B:`Tek seferde 6-7 (2-9) hücre alınabilir.`,C:`Her iki ebeveyn kaynaklı sorunlarda uygulanabilir.`,D:`Doğru: iki yöntemin zaman-hedef farkı doğru karşılaştırılmıştır.`,E:`Trofoektoderm plasentayı oluşturduğundan kritik hücreler alınmaz.`},bilgi:[25,26],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`PGD genetik testlerini (PCR, WGA, FISH, mikroarray, sekanslama) ve PGT alt tiplerini (PGT-A, PGT-SR, PGT-M) açıklamak`,sorular:[{id:`k1-60-q20`,kazanim:7,zorluk:`kolay`,soru:`Yapısal kromozom anomalilerinin embriyoda tespitine yönelik PGT alt tipi hangisidir?`,secenekler:{A:`PGT-HLA`,B:`PGT-A`,C:`PGT-M`,D:`PGT-SR`,E:`PGT-X`},dogru:`D`,aciklama:`PGT-A sayısal, PGT-SR yapısal kromozom anomalilerini, PGT-M monogenik hastalıkları saptar.`,sik_aciklamalari:{A:`Bu derste ayrı bir alt tip olarak tanımlanmamıştır.`,B:`PGT-A anöploidi taramasıdır.`,C:`PGT-M monogenik hastalıklar içindir.`,D:`Doğru: yapısal düzenlemeler içindir.`,E:`Böyle bir alt tip yoktur.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-60-q21`,kazanim:7,zorluk:`orta`,soru:`Çok az miktardaki embriyo DNA'sının analiz öncesi çoğaltılmasını sağlayan yöntem hangisidir?`,secenekler:{A:`FISH`,B:`Tüm genom amplifikasyonu (WGA)`,C:`Karyotip`,D:`İmmünohistokimya`,E:`Western blot`},dogru:`B`,aciklama:`WGA çok az DNA'dan analiz öncesi miktar artırımını sağlar.`,sik_aciklamalari:{A:`FISH DNA'yı çoğaltmaz.`,B:`Doğru: WGA'nın amacıdır.`,C:`Karyotip metafaz hücresi gerektirir.`,D:`İmmünohistokimya protein analizidir.`,E:`Western blot protein analizidir.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-60-q22`,kazanim:7,zorluk:`zor`,soru:`PGD'de kullanılan mikroarray (a-CGH) ile ilgili hangisi doğrudur?`,secenekler:{A:`DNA izole edilmeden hücre içinde analiz yapar`,B:`Yalnızca 5 kromozomu inceleyebilir`,C:`24 kromozomun anöploidisini ve delesyon/duplikasyonları tek işlemde gösterir; işlem 4–5 gün sürdüğünden embriyo dondurulmalıdır`,D:`Sonuç birkaç saatte alınır`,E:`Tek gen nokta mutasyonlarını en iyi gösterir`},dogru:`C`,aciklama:`a-CGH DNA dozaj farklarını saptar ve tüm kromozomları inceler; süre nedeniyle embriyo dondurma gerekir.`,sik_aciklamalari:{A:`Hücre içinde analiz FISH'in özelliğidir.`,B:`Tüm kromozomları inceler.`,C:`Doğru: yöntemin özellikleri doğrudur.`,D:`İşlem 4–5 gün sürer.`,E:`Nokta mutasyonları dizileme ile saptanır.`},bilgi:[28,29],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k07-q04`,kazanim:7,zorluk:`orta`,soru:`Tek hücreden hem miktar artırımı hem mutasyon analizi planlanıyor; dengeli translokasyonlu başka olguda FISH tartışılıyor. Hangi laboratuvar açıklaması doğrudur?`,secenekler:{A:`WGA DNA'yı azaltır`,B:`Tek hücreden analizde WGA ile miktar artırılıp PCR ile mutasyon izlenir; dengeli translokasyonda FISH izolasyonsuz analiz sağlar ancak sinyal üst üste binmesi ve 10 Mb altı-subtelomerik güçlük dezavantajdır`,C:`PCR anöploidi tarar`,D:`FISH DNA izolasyonu gerektirir`,E:`FISH çözünürlüğü sınırsızdır`},dogru:`B`,aciklama:`WGA az DNA'yı çoğaltır, PCR tek gen analizi yapar; FISH izolasyonsuz analizle yapısal anomalilerde kullanılır; dezavantaj sinyal çakışması ve 10 Mb altı güçlük.`,sik_aciklamalari:{A:`WGA miktarı artırır.`,B:`Doğru: iki yöntemin rol ve kısıtları birlikte doğru.`,C:`PCR tek gen içindir.`,D:`Bulunduğu ortamda analiz edilir.`,E:`10 Mb altı ve subtelomerik güçtür.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k07-q05`,kazanim:7,zorluk:`zor`,soru:`Hem translokasyon hem tek gen riski olan çiftte test platformu seçiliyor. Süre, kapsam ve alt tip adlandırması tartışılıyor. Hangi plan doğrudur?`,secenekler:{A:`Mikroarray aynı gün sonuç verir`,B:`Sanger anöploidi tarar`,C:`PGT-M sayısal anomaliye bakar`,D:`Translokasyonlu ve tek gen riskli çiftte mikroarray 24 kromozomu tek işlemde analiz eder ancak 4-5 gün sürdüğünden dondurma gerekir; NGS tek gen+anöploidiyi birlikte yapar (Sanger yalnız tek gen); endikasyona göre PGT-A/SR/M seçilir`,E:`PGT-A monogenik hastalıktır`},dogru:`D`,aciklama:`Mikroarray 24 kromozom dozaj farkını tek işlemde saptar ama 4-5 gün sürüp dondurma gerektirir; Sanger yalnız tek gen, NGS tek gen+anöploidi yapar; PGT-A sayısal, SR yapısal, M monogeniktir.`,sik_aciklamalari:{A:`4-5 gün sürer.`,B:`Sanger yalnız tek gen içindir.`,C:`M monogenik, A sayısal, SR yapısaldır.`,D:`Doğru: süre kısıtı, kapsam farkı ve alt tip seçimi birlikte doğru.`,E:`A sayısal anomalilerdir.`},bilgi:[29,30,31],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k07-q06`,kazanim:7,zorluk:`orta`,soru:`PCR, WGA ve FISH'in PGD'deki rolleri nelerdir?`,secenekler:{A:`WGA artırır, PCR tek gen bakar; FISH yapısal saptar`,B:`PCR anöploidi tarar`,C:`FISH DNA izole eder`,D:`WGA mutasyon saptar`,E:`FISH sayısal taramada üstündür`},dogru:`A`,aciklama:`WGA az DNA'dan analiz öncesi miktar artırımı sağlar; PCR tek gen tanısında kullanılır. FISH DNA'yı yerinde analiz eder, fiksasyon-prob-hibridizasyon basamaklarını içerir ve yapısal anomalilerde kullanılır.`,sik_aciklamalari:{A:`Doğru: üç yöntemin işlev ayrımı doğru verilmiştir.`,B:`PCR tek gen hastalıklarının tanımlanmasında kullanılır.`,C:`FISH DNA'yı izole etmeden bulunduğu ortamda analiz eder.`,D:`WGA miktar artırımını sağlar.`,E:`Dengeli translokasyon gibi yapısal anomalilerde kullanılır.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k07-q07`,kazanim:7,zorluk:`orta`,soru:`Mikroarray kapsamı ve PGT alt tipleri nelerdir?`,secenekler:{A:`Mikroarray tek kromozom bakar`,B:`PGT-A yapısal anomali bakar`,C:`Mikroarray tüm genomu tarar; PGT-A sayısal, PGT-SR yapısal, PGT-M monogeniktir`,D:`PGT-M anöploidi taramasıdır`,E:`NGS biyopsisiz yapılır`},dogru:`C`,aciklama:`Mikroarray dozaj farklarını saptar; 24 kromozomun anöploidileri ile delesyon-duplikasyon-translokasyonlar tek işlemde anlaşılır. PGT-A sayısal, PGT-SR yapısal, PGT-M monogenik bozuklukların tespitidir; NGS'de biyopsi hücresi lizis sonrası özgü primerlerle çoğaltılır.`,sik_aciklamalari:{A:`Tüm kromozomların incelenmesi mümkündür.`,B:`PGT-A sayısal anomalilerin tespitidir.`,C:`Doğru: mikroarray kapsamı ve üç alt tip doğru eşleştirilmiştir.`,D:`PGT-M monogenik gen bozukluklarınındır.`,E:`Biyopsi hücresi lizis solüsyonuna atılarak analiz edilir.`},bilgi:[29,30,31],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:8,metin:`PGD'de genetik danışmanlık, hasta hazırlığı ve kalite/güvenilirlik sorunlarını özetlemek`,sorular:[{id:`k1-60-q23`,kazanim:8,zorluk:`kolay`,soru:`PGD testlerinin güvenilirliğini bozan etkenler arasında aşağıdakilerden hangisi yer alır?`,secenekler:{A:`Uygun donanım`,B:`Yeterli sayıda informatif marker kullanımı`,C:`Optimal laboratuvar koşulları`,D:`Allel drop-out (ADO)`,E:`ICSI kullanımı`},dogru:`D`,aciklama:`Allel drop-out, DNA kontaminasyonu ve amplifikasyon kaybı güvenilirliği bozar.`,sik_aciklamalari:{A:`Uygun donanım riski azaltır.`,B:`İnformatif marker riski azaltır.`,C:`Optimal koşullar riski azaltır.`,D:`Doğru: ADO yanlış sonuca yol açabilir.`,E:`ICSI kontaminasyonu azaltır.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-60-q24`,kazanim:8,zorluk:`orta`,soru:`PGD öncesi genetik danışmanlık ve hasta hazırlığında hangisi doğrudur?`,secenekler:{A:`Yöntem, güven aralığı, yarar ve riskler anlatılır; bilgilendirilmiş onam her iki eşe ayrı ayrı imzalatılır`,B:`Yalnızca annenin onamı yeterlidir`,C:`Riskler anlatılmaz`,D:`Sonuçların %100 kesin olduğu belirtilir`,E:`Danışmanlık PGD sonrası yapılır`},dogru:`A`,aciklama:`Danışmada yöntem, güven aralığı, yarar ve riskler anlatılır; her iki eşten ayrı onam alınır.`,sik_aciklamalari:{A:`Doğru: danışma ve onam ilkeleridir.`,B:`Her iki eşin onamı gerekir.`,C:`Riskler mutlaka anlatılır.`,D:`Testlerin güven aralığı vardır.`,E:`Danışmanlık işlem öncesi yapılır.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-60-q25`,kazanim:8,zorluk:`zor`,soru:`PGD'de embriyonik mozaisizm ile ilgili hangisi doğrudur?`,secenekler:{A:`Mitotik kaynaklı mozaisizm oranları laboratuvarlar arasında farklılık gösterir ve %30'a kadar çıkabilir; mayotik kaynaklı anöploidide tüm hücreler etkilenir`,B:`Mozaisizm PGD'de hiç görülmez`,C:`Mayotik anöploidide yalnızca bazı hücreler etkilenir`,D:`Laboratuvar koşulları mozaisizmi etkilemez`,E:`Mozaisizm biyopsi sonucunu her zaman doğru yansıtır`},dogru:`A`,aciklama:`Mitotik hatalar mozaisizme yol açar; kültür koşulları mitoz hatalarını tetikleyebilir.`,sik_aciklamalari:{A:`Doğru: mozaisizmin kaynakları doğru verilmiştir.`,B:`Mozaisizm önemli bir sorundur.`,C:`Mayotik hatada tüm hücreler etkilenir.`,D:`Laboratuvar koşulları önemlidir.`,E:`Biyopsi tüm embriyoyu temsil etmeyebilir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k08-q04`,kazanim:8,zorluk:`orta`,soru:`Değişken ekspressiviteli OD hastalık için PGD isteyen çiftin danışmanlığında onam ve hazırlık tartışılıyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`PGD öncesi her iki eş ayrı ayrı bilgilendirilip onam verir; azalmış penetrans, değişken ekspressivite ve germinal mozaiklik danışmanlıkta dikkate alınır; myom ve enfeksiyon gibi engeller kadın doğumca tedavi edilir`,B:`Onam yalnızca kadından alınır`,C:`Penetrans danışmanlıkta önemsizdir`,D:`Marker dizaynı gerekmez`,E:`Engeller tedavi edilmeden PGD yapılır`},dogru:`A`,aciklama:`Onam her iki eşe ayrı ayrı imzalatılır; penetrans, ekspressivite, de novo, heterojenite, fenokopi-genokopi ve germinal mozaiklik dikkate alınır; kadın doğum engelleri tedavi eder, genetikçi marker dizaynını tamamlar.`,sik_aciklamalari:{A:`Doğru: onam, genetik fenomenler ve hazırlık üçlüsü tamdır.`,B:`Her iki eşe ayrı ayrı imzalatılır.`,C:`Penetrans-ekspressivite kritiktir.`,D:`İnformatif marker dizaynı tamamlanır.`,E:`Engeller önce tedavi edilir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k08-q05`,kazanim:8,zorluk:`zor`,soru:`PGD raporunda mozaik embriyo izleniyor. Kökenin stimülasyon mu laboratuvar mı olduğu ve non-invaziv seçeneğin yeri tartışılıyor. Hangi yorum doğrudur?`,secenekler:{A:`Mayotik hata yalnızca bazı hücreleri etkiler`,B:`Mitotik hata stimülasyona bağlıdır`,C:`Mozaik embriyo raporunda mayotik kökende tüm hücreler etkilenmiştir (stimülasyon-oosit odaklı), mitotik kökende laboratuvar koşulları sorgulanır (oran %30'a kadar); non-invaziv PGT müdahalesiz analiz hedefler`,D:`Mozaiklik laboratuvardan bağımsızdır`,E:`IVF anomalileri normalden azdır`},dogru:`C`,aciklama:`Mayotik anöploidi tüm hücreleri etkiler (stimülasyon), mitotik laboratuvar koşullarına bağlıdır (mozaiklik %30'a kadar); ni-PGT müdahaleyi azaltmayı hedefler; IVF bebeklerinde anomali biraz fazladır.`,sik_aciklamalari:{A:`Mayotik tüm hücreleri etkiler.`,B:`Mitotik laboratuvar koşullarına bağlıdır.`,C:`Doğru: köken-odak ayrımı ve ni-PGT amacı birlikte doğru.`,D:`Oran laboratuvara göre değişir.`,E:`IVF'te biraz daha fazladır.`},bilgi:[35,36],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k08-q06`,kazanim:8,zorluk:`orta`,soru:`PGD'de danışmanlık ve onam ilkeleri nelerdir?`,secenekler:{A:`Onam tek eşten alınır`,B:`Onam iki eşten ayrı alınır; penetrans ve mozaisizm değerlendirilir`,C:`Riskler anlatılmaz`,D:`Penetrans PGD'yi etkilemez`,E:`Danışmanlık gerekmez`},dogru:`B`,aciklama:`Danışmanlıkta yöntem, güven aralığı, yarar ve riskler anlatılır, sorular cevaplanır ve bilgilendirilmiş onam her iki eşten ayrı alınır. Azalmış penetrans, değişken ekspressivite, de novo mutasyon ve germinal mozaisizm gibi durumlar dikkate alınmalıdır.`,sik_aciklamalari:{A:`Onam her iki eşe ayrı ayrı imzalatılır.`,B:`Doğru: onam kuralı ve dikkat edilecek durumlar birlikte doğru verilmiştir.`,C:`Yararlar ve riskler anlatılmalıdır.`,D:`Azalmış penetrans ve değişken ekspressivite dikkate alınır.`,E:`Yöntem ve güven aralığı danışmanlıkta anlatılır.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k08-q07`,kazanim:8,zorluk:`orta`,soru:`PGD güvenilirliğini bozan etkenler ve mozaisizm nedir?`,secenekler:{A:`ADO güvenilirliği artırır`,B:`Kontaminasyon sonucu iyileştirir`,C:`Mayotik mozaisizm kısmi hücreyi etkiler`,D:`ADO ve kontaminasyon bozar; mayotik mozaisizm tüm hücrelerdedir`,E:`Mozaisizm PGD'yi etkilemez`},dogru:`D`,aciklama:`Test güvenilirliğini allel drop-out (ADO), DNA kontaminasyonu ve amplifikasyon kaybı bozar. Mozaisizm mayotikse tüm hücreler etkilenir; mitotikse laboratuvar koşullarına odaklanılır ve oranlar %30'a çıkabilir; non-invaziv PGT geliştirilmektedir.`,sik_aciklamalari:{A:`ADO güvenilirliği olumsuz etkiler.`,B:`DNA kontaminasyonu sonucu bozar.`,C:`Mayotik kaynaklıysa embriyonun tüm hücreleri etkilenmiştir.`,D:`Doğru: bozan etkenler ve mozaisizm kuralı birlikte doğru verilmiştir.`,E:`Embriyonik mozaisizm %30'a çıkabilir.`},bilgi:[22,35,36],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:9,metin:`IVF sürecinde ovulasyon indüksiyonu, OPU, denüdasyon ve ICSI basamaklarını ve endikasyonlarını açıklamak`,sorular:[{id:`k1-60-q26`,kazanim:9,zorluk:`kolay`,soru:`Oosit toplama (OPU) hCG enjeksiyonundan ne kadar sonra planlanır?`,secenekler:{A:`35–36 saat`,B:`6 saat`,C:`72 saat`,D:`7 gün`,E:`1 saat`},dogru:`A`,aciklama:`Metafaz II 36 saatte gerçekleştiğinden OPU hCG'den 35–36 saat sonra planlanır.`,sik_aciklamalari:{A:`Doğru: OPU zamanlamasıdır.`,B:`Oosit olgunlaşması için çok erkendir.`,C:`Ovulasyon gerçekleşmiş olur.`,D:`Çok geçtir: 7 gün; bu nedenle doğru seçenek değildir.`,E:`Çok erkendir: 1 saat.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-60-q27`,kazanim:9,zorluk:`orta`,soru:`Aşağıdakilerden hangisi ICSI endikasyonudur?`,secenekler:{A:`Total sperm konsantrasyonu <2 milyon/ml`,B:`Normal sperm parametreleri ve ilk IVF denemesi`,C:`Yüksek sperm motilitesi`,D:`Normal morfolojinin %50 olması`,E:`Doğal gebelik öyküsü`},dogru:`A`,aciklama:`ICSI endikasyonları: konsantrasyon <2 milyon/ml, motilite <%5, normal morfoloji <%4, cerrahi sperm vb.`,sik_aciklamalari:{A:`Doğru: ağır oligospermi ICSI endikasyonudur.`,B:`Normal parametrelerde ICSI zorunlu değildir.`,C:`Yüksek motilite endikasyon değildir.`,D:`Normal morfoloji yüksek olduğunda endikasyon yoktur.`,E:`Doğal gebelik endikasyon değildir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-60-q29`,kazanim:9,zorluk:`orta`,soru:`Denüdasyon işlemi aşağıdakilerden hangisini ifade eder?`,secenekler:{A:`Oositin kümülüs-korona hücrelerinden hyaluronidaz ve pipetle ayrılması`,B:`Tek spermin oosit sitoplazmasına enjeksiyonu`,C:`Embriyonun uterusa transferi`,D:`Trofoektoderm biyopsisi`,E:`Embriyonun dondurulması`},dogru:`A`,aciklama:`Denüdasyon oositin çevresindeki kümülüs-korona hücrelerinden ayrılmasıdır; ardından ICSI yapılabilir.`,sik_aciklamalari:{A:`Doğru: denüdasyonun tanımıdır.`,B:`Bu ICSI'dir: tek spermin oosit sitoplazmasına enjeksiyonu.`,C:`Bu embriyo transferidir.`,D:`Bu PGD biyopsisidir.`,E:`Bu vitrifikasyondur.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-60-q28`,kazanim:9,zorluk:`zor`,soru:`IVF sürecinde OPU ile elde edilen oosit sayısı ile ilgili hangisi doğrudur?`,secenekler:{A:`İdeal sayı 8–13'tür; 5'in altı gebelik oranını azaltır, 20'nin üstü OHSS riski oluşturur`,B:`Oosit sayısı arttıkça risk hiç artmaz`,C:`İdeal sayı 1–2'dir`,D:`20'nin üzeri en güvenli aralıktır`,E:`Oosit sayısının gebelik oranına etkisi yoktur`},dogru:`A`,aciklama:`OPU'da ideal oosit sayısı 8–13'tür; az oosit gebelik şansını düşürür, çok sayı OHSS riskini artırır.`,sik_aciklamalari:{A:`Doğru: ideal aralık ve riskler doğrudur.`,B:`Fazla oosit OHSS riskini artırır.`,C:`Az oosit gebelik oranını düşürür.`,D:`20 üzeri OHSS riskidir.`,E:`Oosit sayısı gebelik oranını etkiler.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k09-q05`,kazanim:9,zorluk:`orta`,soru:`Ovulasyon indüksiyonu sonrası OPU zamanlaması ve hedef oosit sayısı tartışılıyor. Aşırı yanıttan endişe ediliyor. Hangi plan doğrudur?`,secenekler:{A:`OPU hCG ile aynı gün yapılır`,B:`İdeal oosit 2'dir`,C:`>20 oosit gebeliği azaltır`,D:`Oositler ısı-pH'dan etkilenmez`,E:`hCG'den 35-36 saat sonra OPU planlanır; ideal 8-13 oosittir (<5 gebelik oranını düşürür, >20 OHSS riski taşır); oositler ısı, osmolarite ve pH değişimlerine duyarlıdır`},dogru:`E`,aciklama:`OPU hCG'den 35-36 saat sonra yapılır; ideal oosit 8-13 (<5 gebelik azalır, >20 OHSS); ısı-osmolarite-pH kritiktir; metafaz 2 36 saatte gerçekleşir.`,sik_aciklamalari:{A:`35-36 saat sonradır.`,B:`İdeal 8-13'tür.`,C:`<5 azaltır, >20 OHSS yapar.`,D:`Üç parametre kritiktir.`,E:`Doğru: zamanlama, sayı ve koşullar birlikte doğru.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k09-q06`,kazanim:9,zorluk:`zor`,soru:`Ağır oligoastenospermili çiftin PGD siklusunda fertilizasyon yöntemi tartışılıyor. Kontaminasyon riski de gündemde. Hangi karar doğrudur?`,secenekler:{A:`ICSI yalnızca normal semende uygulanır`,B:`Total 1 milyon/ml, %3 motil spermi olan çiftte denüdasyon sonrası ICSI endikedir; PGD uygulanan her olguda kontaminasyonu önlemek için ICSI mutlak tercih edilir`,C:`PGD'de klasik IVF tercih edilir`,D:`ICSI kontaminasyonu artırır`,E:`Denüdasyon sperm işlemidir`},dogru:`B`,aciklama:`Denüdasyon kümülüsün hyaluronidazla ayrılması; ICSI tek spermin sitoplazmaya verilmesidir; endikasyon <2 milyon/ml, <%5 motilite, <%4 morfoloji, cerrahi sperm, <3 oosit; PGD'de mutlak tercihtir.`,sik_aciklamalari:{A:`Ağır erkek faktörü endikasyondur.`,B:`Doğru: eşikler ve PGD kuralı birlikte doğru.`,C:`PGD'de ICSI zorunludur.`,D:`Kontaminasyonu önler.`,E:`Denüdasyon oositin soyulmasıdır.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k09-q07`,kazanim:9,zorluk:`orta`,soru:`OPU zamanlaması ve denüdasyon nedir?`,secenekler:{A:`OPU hCG'den 35-36 saat sonradır; denüdasyon korona hücrelerinin ayrılmasıdır`,B:`OPU hCG ile eşzamanlıdır`,C:`Denüdasyon sperm seçimidir`,D:`Metafaz 2 hedeflenmez`,E:`Denüdasyon ICSI'dir`},dogru:`A`,aciklama:`Ovulasyon indüksiyonunda metafaz 2'de sağlıklı oosit hedeflenir ve 36 saatte metafaz 2 gerçekleşir; OPU hCG'den 35-36 saat sonraya planlanır. Denüdasyon kümülüs-korona hücrelerinin hyaluronidaz ve pipetle ayrılmasıdır.`,sik_aciklamalari:{A:`Doğru: OPU zamanlaması ve denüdasyon tanımı birlikte doğru verilmiştir.`,B:`OPU hCG enjeksiyonundan 35-36 saat sonraya planlanır.`,C:`Denüdasyon oositin korona hücrelerinden ayrılmasıdır.`,D:`Metafaz 2'de uygun sayıda sağlıklı oosit amaçlanır.`,E:`ICSI tek spermin sitoplazmaya yerleştirilmesidir.`},bilgi:[33,34],benzer_cikmis:[]},{id:`k1-60-preimplantasyon-genetik-tani-pgt-k09-q08`,kazanim:9,zorluk:`orta`,soru:`ICSI tanımı ve PGD'deki zorunluluğu nedir?`,secenekler:{A:`ICSI doğal fertilizasyondur`,B:`ICSI kontaminasyonu artırır`,C:`ICSI tek sperm enjeksiyonudur ve kontaminasyonu önler`,D:`Erkek infertilitesi ICSI endikasyonu değildir`,E:`ICSI yalnızca PGS'de kullanılır`},dogru:`C`,aciklama:`ICSI tek spermin oosit sitoplazmasına mekanik yerleştirilmesidir ve HLA PGD'de kontaminasyonu önlemek için zorunludur. Erkek infertilitesi ve translokasyon taşıyıcılığı PGD-ICSI endikasyonlarındandır.`,sik_aciklamalari:{A:`Mekanik mikroenjeksiyon işlemidir.`,B:`Kontaminasyonu önlemek için zorunludur.`,C:`Doğru: ICSI tanımı ve amacı birlikte doğru verilmiştir.`,D:`Erkek infertilitesi ile translokasyon taşıyıcılığı endikasyondur.`,E:`PGD uygulamalarında, özellikle HLA'da kullanılır.`},bilgi:[21,34],benzer_cikmis:[]}],ilgili_cikmis:[]}]};export{e as default};